    if (imm_bitlen <= BitImmSize::BITSIZE_8 && id_bitlen <= BitImmSize::BITSIZE_16 && v_bitlen <= BitImmSize::BITSIZE_8) {
        pc_ += Emit<BytecodeInstruction::Format::IMM8_ID16_V8>(std::back_inserter(bytecode_), BytecodeInstruction::Opcode::STSUPERBYNAME_IMM8_ID16_V8, imm, id, v);
        return;
    }

    if (imm_bitlen <= BitImmSize::BITSIZE_16 && id_bitlen <= BitImmSize::BITSIZE_16 && v_bitlen <= BitImmSize::BITSIZE_8) {
        pc_ += Emit<BytecodeInstruction::Format::IMM16_ID16_V8>(std::back_inserter(bytecode_), BytecodeInstruction::Opcode::STSUPERBYNAME_IMM16_ID16_V8, imm, id, v);
        return;
    }
