        pc_ += Emit<BytecodeInstruction::Format::PREF_IMM16>(std::back_inserter(bytecode_), BytecodeInstruction::Opcode::THROW_IFSUPERNOTCORRECTCALL_PREF_IMM16, imm);
        return;
