        pc_ += Emit<BytecodeInstruction::Format::PREF_IMM8_IMM8>(std::back_inserter(bytecode_), BytecodeInstruction::Opcode::CALLRUNTIME_STSENDABLEVAR_PREF_IMM8_IMM8, imm1, imm2);
