    case BytecodeInstruction::Opcode::JNSTRICTEQ_V8_IMM8:
        UpdateBranchByFormat<BytecodeInstruction::Format::V8_IMM8>(insn, offs);
        return;
    case BytecodeInstruction::Opcode::JMP_IMM32:
        UpdateBranchByFormat<BytecodeInstruction::Format::IMM32>(insn, offs);
        return;
    case BytecodeInstruction::Opcode::JEQZ_IMM32:
        UpdateBranchByFormat<BytecodeInstruction::Format::IMM32>(insn, offs);
